        if limit < 0:
            raise ValueError("Budget limit cannot be negative")
        self.budgets[category].limit = limit

    def adjust_budget(self, category: Category, delta: float) -> None:
        if self.budgets[category].limit + delta < 0:
            raise ValueError("Adjusted budget limit cannot be negative")
        self.budgets[category].limit += delta

    def get_category_budget(self, category: Category) -> Budget:
        return self.budgets[category]

