            "remaining": remaining,
            "user_contributions": user_contributions,
            "category_breakdown": {
                cat.value: self.budgets[cat].current_spending for cat in Category
            },
            "over_limit_categories": [
                cat.value for cat in Category if self.budgets[cat].is_over_limit()
            ],
        }

    # --- Optimization ---
    def suggest_optimizations(self) -> List[Dict]:
        suggestions = []
        for cat, budget in self.budgets.items():
            if budget.is_over_limit():
                overage = budget.current_spending - budget.limit
                suggestions.append({
                    "type": "over_limit",
                    "category": cat.value,
                    "overage_amount": overage,
                    "message": f"Category '{cat.value}' is over budget by ${overage:.2f}. Consider reducing spending."
