from typing import Dict, List, Optional, Tuple
from dataclasses import dataclass, field
from enum import Enum
import copy


class Category(Enum):
    GROCERIES = "groceries"
    ENTERTAINMENT = "entertainment"
    UTILITIES = "utilities"
    TRANSPORTATION = "transportation"
    HEALTHCARE = "healthcare"
    OTHER = "other"


@dataclass
class Expense:
    """Represents a single expense entry."""
    user_id: str
    amount: float
    category: Category
    description: str = ""

    def __post_init__(self):
        if self.amount < 0:
            raise ValueError("Expense amount cannot be negative.")


@dataclass
class User:
    """Represents a user in the system."""
    user_id: str
    name: str
    expenses: List[Expense] = field(default_factory=list)

    def add_expense(self, expense: Expense) -> None:
        if expense.user_id != self.user_id:
            raise ValueError("Expense user_id must match the user's ID.")
        self.expenses.append(expense)

    def get_total_spent(self, category: Optional[Category] = None) -> float:
        if category is None:
            return sum(e.amount for e in self.expenses)
        return sum(e.amount for e in self.expenses if e.category == category)


@dataclass
class Budget:
    """Budget configuration for a category."""
    category: Category
    limit: float
    current_spent: float = 0.0

    def update_spent(self, amount: float) -> None:
        self.current_spent += amount

    def is_over_limit(self) -> bool:
        return self.current_spent > self.limit

    def remaining(self) -> float:
        return max(0.0, self.limit - self.current_spent)


class MultiAgentBudgetOptimizer:
    """
    Manages multi-user budgeting with collaborative optimization.
    """

    def __init__(self):
        self.users: Dict[str, User] = {}
        self.budgets: Dict[Category, Budget] = {
            cat: Budget(category=cat, limit=0.0) for cat in Category
        }
        self.group_budget_limits: Dict[Category, float] = {
            cat: 0.0 for cat in Category
        }

    # --- User Management ---
    def add_user(self, user_id: str, name: str) -> None:
        if user_id in self.users:
            raise ValueError(f"User with ID '{user_id}' already exists.")
        self.users[user_id] = User(user_id=user_id, name=name)

    def remove_user(self, user_id: str) -> None:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        del self.users[user_id]

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    # --- Budget Management ---
    def set_budget_limit(self, category: Category, limit: float) -> None:
        if limit < 0:
            raise ValueError("Budget limit cannot be negative.")
        self.group_budget_limits[category] = limit
        if category in self.budgets:
            self.budgets[category].limit = limit

    def adjust_budget_limit(self, category: Category, new_limit: float) -> None:
        self.set_budget_limit(category, new_limit)

    # --- Expense Management ---
    def add_expense(self, user_id: str, amount: float, category: Category,
                    description: str = "") -> Expense:
        if user_id not in self.users:
            raise KeyError(f"User with ID '{user_id}' does not exist.")
        if amount <= 0:
            raise ValueError("Expense amount must be positive.")

        expense = Expense(user_id=user_id, amount=amount, category=category,
                          description=description)
        self.users[user_id].add_expense(expense)
        self.budgets[category].update_spent(amount)
        return expense

    def get_total_group_spent(self, category: Optional[Category] = None) -> float:
        if category is None:
            return sum(user.get_total_spent() for user in self.users.values())
        return sum(user.get_total_spent(category) for user in self.users.values())

    def get_remaining_budget(self, category: Optional[Category] = None) -> Dict[Category, float]:
        if category:
            return {category: self.budgets[category].remaining()}
        return {cat: self.budgets[cat].remaining() for cat in Category}

