                    transfer_amount = min(
                        self.budgets[over_cat].current_spent - self.budgets[over_cat].limit,
                        self.budgets[under_cat].limit - self.budgets[under_cat].current_spent
                    )
                    if transfer_amount > 0:
                        suggestions.append({
                            "type": "reallocate",
                            "from_category": under_cat.value,
                            "to_category": over_cat.value,
                            "amount": transfer_amount,
                            "message": f"Consider reallocating ${transfer_amount:.2f} from '{under_cat.value}' to '{over_cat.value}'."
